ALTER TABLE public.profiles ADD COLUMN email text, ADD COLUMN nombre text NOT NULL DEFAULT '', ADD COLUMN estado text NOT NULL DEFAULT 'Invitado', ADD COLUMN fecha_alta timestamptz NOT NULL DEFAULT now(); CREATE UNIQUE INDEX profiles_email_unique ON public.profiles(lower(email)) WHERE email IS NOT NULL; CREATE UNIQUE INDEX one_super_admin ON public.user_roles(role) WHERE role='super_admin';
CREATE FUNCTION public.is_super_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='super_admin') $$; CREATE FUNCTION public.is_directiva() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN('super_admin','directiva')) $$; CREATE OR REPLACE FUNCTION public.has_club_role(r public.club_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role=r OR (r='directiva' AND role='super_admin'))) $$;
CREATE TABLE public.equipo_invitaciones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,nombre text NOT NULL,socio_id uuid REFERENCES public.socios(id),user_id uuid,estado text NOT NULL DEFAULT 'Invitado',fecha_alta timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.equipo_invitaciones TO service_role; GRANT SELECT,INSERT,UPDATE,DELETE ON public.equipo_invitaciones TO authenticated; ALTER TABLE public.equipo_invitaciones ENABLE ROW LEVEL SECURITY; CREATE POLICY equipo_super ON public.equipo_invitaciones FOR ALL TO authenticated USING(public.is_super_admin()) WITH CHECK(public.is_super_admin());
CREATE TABLE public.registro_permisos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fecha timestamptz NOT NULL DEFAULT now(),actor_id uuid,afectado_id uuid NOT NULL,accion text NOT NULL,motivo text NOT NULL DEFAULT ''); GRANT SELECT ON public.registro_permisos TO authenticated; GRANT ALL ON public.registro_permisos TO service_role; ALTER TABLE public.registro_permisos ENABLE ROW LEVEL SECURITY; CREATE POLICY historial_super ON public.registro_permisos FOR SELECT TO authenticated USING(public.is_super_admin());
CREATE TABLE public.ajustes_club(id boolean PRIMARY KEY DEFAULT true CHECK(id),whatsapp_club text NOT NULL DEFAULT '',nombre_club text NOT NULL DEFAULT 'Real Unión Lucense F.S.',temporada_actual text NOT NULL DEFAULT '2026/27',email_club text NOT NULL DEFAULT ''); GRANT SELECT ON public.ajustes_club TO anon,authenticated; GRANT UPDATE ON public.ajustes_club TO authenticated; GRANT ALL ON public.ajustes_club TO service_role; ALTER TABLE public.ajustes_club ENABLE ROW LEVEL SECURITY; CREATE POLICY ajustes_lectura ON public.ajustes_club FOR SELECT TO anon,authenticated USING(true); CREATE POLICY ajustes_super ON public.ajustes_club FOR UPDATE TO authenticated USING(public.is_super_admin()) WITH CHECK(public.is_super_admin());
CREATE FUNCTION public.validate_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.whatsapp_club<>'' AND NEW.whatsapp_club !~ '^[1-9][0-9]{7,14}$' THEN RAISE EXCEPTION 'WhatsApp debe incluir prefijo de país y solo dígitos'; END IF; RETURN NEW; END $$; CREATE TRIGGER settings_validation BEFORE UPDATE OR INSERT ON public.ajustes_club FOR EACH ROW EXECUTE FUNCTION public.validate_settings();
CREATE FUNCTION public.guard_roles() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND (coalesce(NEW.role,OLD.role) IN('directiva','super_admin') OR OLD.role IN('directiva','super_admin')) THEN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; IF coalesce(NEW.user_id,OLD.user_id)=auth.uid() AND current_setting('club.transfer',true) IS DISTINCT FROM 'yes' THEN RAISE EXCEPTION 'No puedes cambiar tus propios permisos'; END IF; END IF; RETURN coalesce(NEW,OLD); END $$; CREATE TRIGGER role_guard BEFORE INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_roles();
CREATE FUNCTION public.audit_roles() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(NEW.role,OLD.role) IN('directiva','super_admin') THEN INSERT INTO public.registro_permisos(actor_id,afectado_id,accion,motivo) VALUES(auth.uid(),coalesce(NEW.user_id,OLD.user_id),CASE WHEN current_setting('club.transfer',true)='yes' THEN 'transferir_super_admin' WHEN TG_OP='DELETE' THEN 'quitar_directiva' ELSE 'añadir_directiva' END,coalesce(current_setting('club.reason',true),'')); END IF; RETURN coalesce(NEW,OLD); END $$; CREATE TRIGGER role_audit AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_roles();
CREATE FUNCTION public.quitar_directiva(p_user uuid,p_motivo text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() OR p_user=auth.uid() OR length(trim(p_motivo))=0 THEN RAISE EXCEPTION 'No autorizado o motivo vacío'; END IF; PERFORM set_config('club.reason',p_motivo,true); DELETE FROM public.user_roles WHERE user_id=p_user AND role='directiva'; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user AND socio_id IS NOT NULL) THEN INSERT INTO public.user_roles(user_id,role) VALUES(p_user,'socia'); END IF; UPDATE public.equipo_invitaciones SET estado='Retirado' WHERE user_id=p_user; END $$;
CREATE FUNCTION public.transferir_super_admin(nuevo_perfil_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_super_admin() OR nuevo_perfil_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=nuevo_perfil_id AND role='directiva') THEN RAISE EXCEPTION 'No autorizado'; END IF; PERFORM set_config('club.transfer','yes',true); UPDATE public.user_roles SET role='directiva' WHERE user_id=auth.uid(); UPDATE public.user_roles SET role='super_admin' WHERE user_id=nuevo_perfil_id; END $$;
CREATE FUNCTION public.guard_admin_profiles() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=coalesce(NEW.id,OLD.id) AND role IN('directiva','super_admin')) AND NOT public.is_super_admin() THEN RAISE EXCEPTION 'Solo Super admin'; END IF; RETURN coalesce(NEW,OLD); END $$; CREATE TRIGGER admin_profile_guard BEFORE INSERT OR UPDATE OR DELETE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_admin_profiles();
REVOKE ALL ON FUNCTION public.quitar_directiva(uuid,text),public.transferir_super_admin(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.quitar_directiva(uuid,text),public.transferir_super_admin(uuid),public.is_super_admin(),public.is_directiva() TO authenticated;